"""Apply verified gold_chunk_id corrections to the eval set."""import jsonfrom pathlib import PathCORRECTIONS = {    "q002": ["1505.04597_chunk5"],    "q008": ["1706.03762_chunk5"],    "q010": ["1706.03762_chunk6"],    "q011": ["1706.03762_chunk9"],    "q013": ["2010.11929_chunk1"],    "q014": ["2010.11929_chunk1"],    "q015": ["2103.14030_chunk2", "2103.14030_chunk8"],    "q017": ["2002.05709_chunk7"],    "q018": ["2002.05709_chunk3"],    "q021": ["1905.11946_chunk2"],    "q023": ["1708.02002_chunk6"],    "q026": ["2005.12872_chunk4"],    "q028": ["2005.12872_chunk2"],    "q031": ["2103.14030_chunk2"],    "q032": ["2010.11929_chunk4"],    "q033": ["1706.03762_chunk9"],    "q034": ["1708.02002_chunk4"],}NOTE_ADDITIONS = {    "q002": " VERIFIED: gold ranks #1 for keyword phrasing (0.440) but drops out of top-20 for natural-language phrasing.",    "q031": " VERIFIED: gold contains 'hierarchical feature maps' verbatim; a keyword query for that exact phrase returned zero Swin chunks.",    "q032": " VERIFIED: gold contains 'Layernorm (LN) is applied before every block' verbatim, yet did not rank top-5 for that exact phrase - and ranked 3rd for an unrelated projection-head query.",}def main(path: str = "eval/questions.jsonl"):    p = Path(path)    lines = [json.loads(l) for l in p.read_text().splitlines() if l.strip()]    changed = 0    for q in lines:        qid = q["id"]        if qid in CORRECTIONS:            old = q["gold_chunk_ids"]            new = CORRECTIONS[qid]            if old != new:                print(f"{qid}: {old} -> {new}")                q["gold_chunk_ids"] = new                changed += 1        if qid in NOTE_ADDITIONS and NOTE_ADDITIONS[qid] not in q["notes"]:            q["notes"] = q["notes"] + NOTE_ADDITIONS[qid]    p.write_text("\n".join(json.dumps(q) for q in lines) + "\n")    print(f"\n{changed} gold id(s) updated, written to {path}")if __name__ == "__main__":    main()